package deliveryfee.mapper;

import deliveryfee.dto.BaseFeeResponse;
import deliveryfee.entity.BaseFee;
import java.util.List;
import org.mapstruct.Mapper;
import org.mapstruct.MappingConstants;
import org.mapstruct.ReportingPolicy;

/**
 * Converts base fee entities to REST API objects. The implementation is generated by MapStruct
 */
@Mapper(componentModel = MappingConstants.ComponentModel.SPRING,
        unmappedTargetPolicy = ReportingPolicy.ERROR)
public interface BaseFeeMapper {

    /**
     * Converts a base fee entity to a response.
     *
     * @param baseFee entity to convert
     * @return response with the same values
     */
    BaseFeeResponse toResponse(BaseFee baseFee);

    /**
     * Converts a list of base fee entities to responses.
     *
     * @param baseFees entities to convert
     * @return responses in the same order
     */
    List<BaseFeeResponse> toResponses(List<BaseFee> baseFees);
}